import random
import os
import struct

# This generator produces valid arbitrary binary inputs for base64_encode.
# Strategy:
# - Produce a variety of sizes (including 0, small, moderate, and near the 4096 limit used by the fuzzer infra).
# - Mix content patterns: all-zero, incremental, high-entropy random, repeated bytes, ASCII text, and lengths that
#   are interesting w.r.t Base64 grouping (mod 3 boundaries).
# - Ensure determinism per provided seed while remaining varied between calls with different seeds.
# - Keep output size <= 4096 bytes.

_MAX = 4096


def _rand_choice(rng, items):
    return items[rng.randrange(len(items))]


def _gen_size(rng):
    # Favor sizes around Base64 boundaries and a spread of ranges.
    interesting = [0, 1, 2, 3, 4, 5, 6, 7, 8, 15, 16, 31, 32, 47, 48, 63, 64, 65, 127, 128, 255, 256, 511, 512, 1023, 1024, 2047, 2048, 3072, 4095]
    if rng.random() < 0.6:
        # Pick from interesting, but cap at _MAX
        sz = _rand_choice(rng, [s for s in interesting if s <= _MAX])
    else:
        # Weighted random up to _MAX
        # Bias toward smaller sizes but allow large
        p = rng.random()
        if p < 0.6:
            sz = rng.randint(0, 128)
        elif p < 0.85:
            sz = rng.randint(0, 1024)
        else:
            sz = rng.randint(0, _MAX)
    return sz


def _pattern_zero(sz):
    return b"\x00" * sz


def _pattern_increment(sz, start):
    return bytes(((start + i) & 0xFF) for i in range(sz))


def _pattern_repeat_byte(sz, bval):
    return bytes([bval]) * sz


def _pattern_random(sz, rng):
    # Deterministic via rng
    return bytes(rng.getrandbits(8) for _ in range(sz))


def _pattern_ascii(sz, rng):
    # Printable ASCII with occasional whitespace/newlines
    chars = [
        *(ord(c) for c in "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"),
        0x20, 0x09, 0x0A, 0x0D, ord('='), ord(':'), ord(','), ord(';'), ord('{'), ord('}'), ord('['), ord(']'), ord('('), ord(')'), ord('-'), ord('_'), ord('.'), ord('!'), ord('?')
    ]
    return bytes(_rand_choice(rng, chars) for _ in range(sz))


def _pattern_blocks(sz, rng):
    # Compose from blocks with varied contents to exercise transitions.
    out = bytearray()
    while len(out) < sz:
        mode = rng.randrange(6)
        block_len = min(sz - len(out), max(1, int(rng.expovariate(1/32))))
        if mode == 0:
            out.extend(_pattern_random(block_len, rng))
        elif mode == 1:
            out.extend(_pattern_repeat_byte(block_len, rng.randrange(256)))
        elif mode == 2:
            out.extend(_pattern_increment(block_len, rng.randrange(256)))
        elif mode == 3:
            out.extend(_pattern_ascii(block_len, rng))
        elif mode == 4:
            out.extend(_pattern_zero(block_len))
        else:
            # Mixed small chunks
            sub = min(block_len, 12)
            for _ in range(block_len // sub):
                out.extend(_pattern_random(sub, rng))
            out.extend(_pattern_random(block_len % sub, rng))
    return bytes(out[:sz])


def _bias_length_to_mod3(sz, rng):
    # Occasionally force sizes to specific mod 3 to exercise Base64 padding behavior
    if sz == 0:
        return 0
    if rng.random() < 0.7:
        target_mod = _rand_choice(rng, [0, 1, 2])
        # adjust by +/- up to 2 if possible
        delta_opts = []
        for d in (-2, -1, 0, 1, 2):
            new = sz + d
            if 0 <= new <= _MAX and (new % 3) == target_mod:
                delta_opts.append(new)
        if delta_opts:
            return _rand_choice(rng, delta_opts)
    return sz


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Choose a base size and adjust around mod 3 boundaries
    sz = _gen_size(rng)
    sz = _bias_length_to_mod3(sz, rng)

    # Choose a content strategy
    strategy = _rand_choice(rng, [
        'zero', 'increment', 'repeat', 'random', 'ascii', 'blocks'
    ])

    if strategy == 'zero':
        data = _pattern_zero(sz)
    elif strategy == 'increment':
        start = rng.randrange(256)
        data = _pattern_increment(sz, start)
    elif strategy == 'repeat':
        bval = rng.randrange(256)
        data = _pattern_repeat_byte(sz, bval)
    elif strategy == 'random':
        data = _pattern_random(sz, rng)
    elif strategy == 'ascii':
        data = _pattern_ascii(sz, rng)
    else:
        data = _pattern_blocks(sz, rng)

    # Occasionally prefix or suffix small markers to diversify boundaries without breaking validity
    if rng.random() < 0.3 and len(data) < _MAX:
        # Small prefix of random length 0-8
        pre_len = min(rng.randrange(9), _MAX - len(data))
        if pre_len:
            prefix_mode = rng.randrange(3)
            if prefix_mode == 0:
                prefix = _pattern_zero(pre_len)
            elif prefix_mode == 1:
                prefix = _pattern_random(pre_len, rng)
            else:
                prefix = _pattern_increment(pre_len, rng.randrange(256))
            data = prefix + data
    if rng.random() < 0.3 and len(data) < _MAX:
        suf_len = min(rng.randrange(9), _MAX - len(data))
        if suf_len:
            suffix_mode = rng.randrange(3)
            if suffix_mode == 0:
                suffix = _pattern_zero(suf_len)
            elif suffix_mode == 1:
                suffix = _pattern_random(suf_len, rng)
            else:
                suffix = _pattern_increment(suf_len, rng.randrange(256))
            data = data + suffix

    # Ensure size cap
    if len(data) > _MAX:
        data = data[:_MAX]

    return data
